def _plain(value: str) -> str:
    return re.sub(r"\s+", " ", re.sub(r"<[^>]+>", "", html.unescape(value))).strip()


def resolve_crossref(doi: str, authority: str) -> dict:
    response = requests.get(
        f"https://api.crossref.org/works/{doi}",
        headers={"User-Agent": "Noemorph citation audit (research catalog)"},
        timeout=30,
    )
    response.raise_for_status()
    message = response.json()["message"]
    authors = []
    for author in message.get("author", []):
        literal = author.get("name")
        if literal:
            authors.append(_plain(literal))
        else:
            full = " ".join(part for part in (author.get("given"), author.get("family")) if part)
            if full:
                authors.append(_plain(full))
    years = []
    for key in ("published-online", "published-print", "published", "issued", "created"):
        parts = message.get(key, {}).get("date-parts", [])
        if parts and parts[0] and isinstance(parts[0][0], int):
            years.append(parts[0][0])
    title = _plain((message.get("title") or [""])[0])
    venue = _plain((message.get("container-title") or [""])[0])
    return {
        "title": title,
        "authors": "; ".join(authors),
        "year": min(years),
        "venue": venue,
        "doi": doi.lower(),
        "url": f"https://doi.org/{doi}",
        "authority": authority,
        "verification": "doi-resolved",
        "retrieved": RETRIEVED,
    }


def build_sources() -> dict[str, dict]:
    result = {key: resolve_crossref(doi, authority) for key, (doi, authority) in SOURCES.items()}
    result.update(copy.deepcopy(LOCATOR_SOURCES))
    return result


def make_record(
    *,
    slug: str,
    name: str,
    aliases: list[str],
    kind: str,
    domain: str,
    tradition: str,
    status: str,
    status_note: str,
    summary: str,
    proponents: list[str],
    era: str,
    year: int,
    scope: str,
    keywords: list[str],
    boundary: str,
    target: str,
    level: str,
    does_not: str,
    basis: list[str],
    limitations: list[str],
    independence: str,
    questions: list[str],
    sources: list[str],
) -> dict:
    kind_codes = {
        "Scientific theory": ["CT", "NF"],
        "Model or framework": ["MF", "NF"],
        "Argument / challenge": ["AC", "NF"],
        "Philosophical position": ["PP", "NF"],
    }[kind]
    return {
        "id": f"emerging-breadth-{slug}",
        "name": name,
        "aliases": aliases,
        "kind": kind,
        "kind_codes": kind_codes,
        "domain": domain,
        "tradition": tradition,
        "status": status,
        "status_note": status_note,
        "summary": summary,
        "proponents": proponents,
        "era": era,
        "year": year,
        "scope": scope,
        "keywords": keywords,
        "boundary_note": boundary,
        "claim_scope": {"target": target, "level": level, "does_not_establish": does_not},
        "evidence_profile": {
            "basis": basis,
            "limitations": limitations,
            "independence": independence,
        },
        "open_questions": questions,
        "review_state": "provisional",
        "citations": [copy.deepcopy(CITATIONS[key]) for key in sources],
    }


